
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,role TEXT NOT NULL,status TEXT NOT NULL,deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS accounts(id INTEGER PRIMARY KEY,name TEXT NOT NULL,root_id INTEGER NOT NULL,platform TEXT NOT NULL,status TEXT NOT NULL,deleted INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profiles(account_id INTEGER PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('paid','free')),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS usage(id INTEGER PRIMARY KEY,account_id INTEGER NOT NULL,root_id INTEGER NOT NULL,user_id INTEGER NOT NULL,amount TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS usage_root_time ON usage(root_id,created_at);
CREATE TABLE IF NOT EXISTS cycles(id INTEGER PRIMARY KEY AUTOINCREMENT,account_id INTEGER NOT NULL,name TEXT NOT NULL,cost_fen INTEGER NOT NULL CHECK(cost_fen>=0),creditor_id INTEGER NOT NULL,start TEXT NOT NULL,end TEXT,status TEXT NOT NULL DEFAULT 'open',version INTEGER NOT NULL DEFAULT 1,settlement_id INTEGER,start_mode TEXT NOT NULL DEFAULT 'exact',start_lower TEXT,start_upper TEXT,start_confirmed INTEGER NOT NULL DEFAULT 1,start_confirmed_by INTEGER,start_confirmed_at TEXT,start_source_usage_id INTEGER,renewed_from_cycle_id INTEGER,start_locked INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS cycle_account ON cycles(account_id,start);
CREATE TABLE IF NOT EXISTS previews(id TEXT PRIMARY KEY,actor_id INTEGER NOT NULL,payload TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settlements(id INTEGER PRIMARY KEY AUTOINCREMENT,cycle_id INTEGER,expense_id INTEGER,snapshot TEXT NOT NULL,digest TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',drift INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settlement_usage(settlement_id INTEGER NOT NULL,usage_id INTEGER NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(settlement_id,usage_id));
CREATE TABLE IF NOT EXISTS batches(id INTEGER PRIMARY KEY AUTOINCREMENT,payer_id INTEGER NOT NULL,creditor_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,settlement_id INTEGER NOT NULL,cycle_id INTEGER,expense_id INTEGER,payer_id INTEGER NOT NULL,creditor_id INTEGER NOT NULL,payer_name TEXT NOT NULL,creditor_name TEXT NOT NULL,account_name TEXT NOT NULL,amount_fen INTEGER NOT NULL CHECK(amount_fen>0),status TEXT NOT NULL DEFAULT 'pending',batch_id INTEGER,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,submitted_at TEXT,paid_at TEXT);
CREATE INDEX IF NOT EXISTS order_payer ON orders(payer_id,status);
CREATE INDEX IF NOT EXISTS order_creditor ON orders(creditor_id,status);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,title TEXT NOT NULL,order_id INTEGER,read INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id INTEGER NOT NULL,action TEXT NOT NULL,entity_id INTEGER,payload TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS requests(actor_id INTEGER NOT NULL,key TEXT NOT NULL,signature TEXT NOT NULL,response TEXT NOT NULL,PRIMARY KEY(actor_id,key));
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,token TEXT NOT NULL,csrf TEXT NOT NULL,expires_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS usage_details(usage_id INTEGER PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS expenses(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,cost_fen INTEGER NOT NULL,incurred_on TEXT NOT NULL,creditor_id INTEGER NOT NULL,allocation_mode TEXT NOT NULL,members TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',version INTEGER NOT NULL DEFAULT 1,settlement_id INTEGER,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bill_imports(id INTEGER PRIMARY KEY AUTOINCREMENT,cycle_id INTEGER NOT NULL,file_name TEXT NOT NULL,file_hash TEXT NOT NULL,rows TEXT NOT NULL,created_by INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(cycle_id,file_hash));
CREATE TABLE IF NOT EXISTS bill_previews(id TEXT PRIMARY KEY,actor_id INTEGER NOT NULL,cycle_id INTEGER NOT NULL,payload TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS account_deletions(id INTEGER PRIMARY KEY AUTOINCREMENT,account_id INTEGER NOT NULL,settlement_id INTEGER NOT NULL UNIQUE,account_name TEXT NOT NULL,account_created_at TEXT NOT NULL,actor_id INTEGER NOT NULL,session_id TEXT,status TEXT NOT NULL DEFAULT 'queued',version INTEGER NOT NULL DEFAULT 1,error TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS deletion_account_status ON account_deletions(account_id,status);
CREATE TABLE IF NOT EXISTS netting_payments(id INTEGER PRIMARY KEY AUTOINCREMENT,user_a INTEGER NOT NULL,user_b INTEGER NOT NULL,payer_id INTEGER,creditor_id INTEGER,amount_fen INTEGER NOT NULL CHECK(amount_fen>=0),offset_fen INTEGER NOT NULL CHECK(offset_fen>=0),a_to_b_fen INTEGER NOT NULL,b_to_a_fen INTEGER NOT NULL,actor_id INTEGER NOT NULL,created_at TEXT NOT NULL,digest TEXT NOT NULL,snapshot TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS netting_participants ON netting_payments(user_a,user_b,id);
CREATE TRIGGER IF NOT EXISTS netting_immutable_update BEFORE UPDATE ON netting_payments BEGIN SELECT RAISE(ABORT,'netting payments are immutable'); END;
CREATE TRIGGER IF NOT EXISTS netting_immutable_delete BEFORE DELETE ON netting_payments BEGIN SELECT RAISE(ABORT,'netting payments are immutable'); END;
